<?php $statuses=['RASCUNHO'=>'Rascunho','FINALIZADO'=>'Finalizado'];$pageUrl=static fn(int $number):string=>'/apc/planos?'.http_build_query($filters+['pagina'=>$number]);ob_start();?>
<section class="page-heading"><div><p class="eyebrow">Planejamento e entregas</p><h1>Planos de ação APC</h1><p>Consulte os planos existentes e as entregas dos alunos. O <a href="/apc">envio simplificado de arquivos</a> é um fluxo separado.</p></div><?php if($canCreate):?><a class="button primary" href="/apc/planos/novo">Criar plano de ação</a><?php endif;?></section>
<form method="get" action="/apc/planos" class="card apc-filter-grid"><label>Ano letivo <input type="number" name="ano" min="2000" max="2100" value="<?=e($filters['ano'])?>"></label><label>Evento <select name="evento"><option value="">Todos</option><?php foreach($events as$event):?><option value="<?=e($event['id'])?>" <?=$filters['evento']==$event['id']?'selected':''?>><?=e(date('d/m/Y',strtotime($event['data'])).' · '.$event['titulo'])?></option><?php endforeach;?></select></label><label>Turma <select name="turma"><option value="">Todas</option><?php foreach($classes as$class):?><option value="<?=e($class['id'])?>" <?=$filters['turma']==$class['id']?'selected':''?>><?=e($class['nome'])?></option><?php endforeach;?></select></label><label>Situação <select name="status"><option value="">Todas</option><?php foreach($statuses as$value=>$label):?><option value="<?=e($value)?>" <?=$filters['status']===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><div class="actions"><button class="primary">Filtrar planos</button><a class="button" href="/apc/planos">Limpar</a></div></form>
<section class="card"><h2>Planos encontrados <span class="badge"><?=e($total)?></span></h2><p>Rascunho indica preenchimento em andamento. A edição e o registro de entregas dependem da janela de cada plano.</p><?php if(!$rows):?><p class="empty-state">Nenhum plano corresponde aos filtros. Consulte também o <a href="/apc/calendario">calendário APC</a>.</p><?php else:?><p>Mostrando <?=e(($page-1)*25+1)?>–<?=e(min($page*25,$total))?> de <?=e($total)?> planos.</p><div class="table"><table><thead><tr><th>Evento</th><th>Turma / professor</th><th>Componente</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as$row):?><tr><td data-label="Evento"><strong><?=e(date('d/m/Y',strtotime($row['evento_data'])))?></strong><small><?=e($row['evento_titulo'])?></small></td><td data-label="Turma / professor"><?=e($row['turma_nome_snapshot'])?><small><?=e($row['professor_nome_snapshot'])?></small></td><td data-label="Componente"><?=e($row['componente_curricular'])?></td><td data-label="Situação"><?=e($statuses[$row['status']]??$row['status'])?></td><td data-label="Ações" class="row-actions"><a class="button small-button" href="/apc/planos/<?=e($row['id'])?>">Consultar plano</a><a class="button small-button" href="/apc/planos/<?=e($row['id'])?>/entregas">Entregas dos alunos</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($pages>1):?><nav class="pagination actions" aria-label="Páginas dos planos"><?php if($page>1):?><a class="button" href="<?=e($pageUrl($page-1))?>">Anterior</a><?php endif;?><span>Página <?=e($page)?> de <?=e($pages)?></span><?php if($page<$pages):?><a class="button" href="<?=e($pageUrl($page+1))?>">Próxima</a><?php endif;?></nav><?php endif;?></section>
<?php $content=ob_get_clean();require dirname(__DIR__,3).'/preconselho-web/resources/views/layout.php';
